type CartLine = { sku: string; quantity: number };
type CartAction =
  | { type: "add"; line: CartLine }
  | { type: "setQuantity"; sku: string; quantity: number }
  | { type: "clear" };

function reduceCart(lines: CartLine[], action: CartAction): CartLine[] {
  switch (action.type) {
    case "add": {
      const existing = lines.find((line) => line.sku === action.line.sku);
      if (existing === undefined) {
        return [...lines, action.line];
      }
      return lines.map((line) =>
        line.sku === action.line.sku
          ? { ...line, quantity: line.quantity + action.line.quantity }
          : line,
      );
    }
    case "setQuantity": {
      if (action.quantity <= 0) {
        return lines.filter((line) => line.sku !== action.sku);
      }
      return lines.map((line) =>
        line.sku === action.sku ? { ...line, quantity: action.quantity } : line,
      );
    }
    case "clear":
      return [];
    default:
      return lines;
  }
}
